import struct
b=open('/workspace/poc','rb').read(); num=struct.unpack('>H',b[4:6])[0]
for i in range(num):
 tag,cs,off,l=struct.unpack('>4sIII',b[12+16*i:28+16*i])
 if tag==b'gvar':
  g=b[off:off+l]
  major,minor,axisCount,sharedTupleCount,offsetToSharedTuples,glyphCount,flags,offsetToData=struct.unpack('>HHHHIHHI',g[:20])
  print('gvar hdr', major,minor,axisCount,sharedTupleCount,offsetToSharedTuples,glyphCount,flags,offsetToData)
  arrpos=off+20
  n=glyphCount+1
  print('need bytes', (4 if flags&1 else 2)*n, 'avail before dataZ', off+offsetToData-arrpos)
  offs=[]
  for j in range(n):
   if flags&1: offs.append(struct.unpack('>I', b[arrpos+4*j:arrpos+4*j+4])[0])
   else: offs.append(2*struct.unpack('>H', b[arrpos+2*j:arrpos+2*j+2])[0])
  print('first last offsets',offs[:20],offs[-10:], 'total', offs[-1])
  print('nonmono', [(j,offs[j],offs[j+1]) for j in range(glyphCount) if offs[j]>offs[j+1]][:20])
  for j in range(min(glyphCount, 20)):
   s,e=offs[j],offs[j+1]
   if e>s: print('glyph',j,s,e,e-s,'abs',off+offsetToData+s, b[off+offsetToData+s:off+offsetToData+min(e,s+16)].hex())
